describe('Table Row Selection Highlighting', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('table').should('be.visible');
  });

  it('should highlight a selected row in a different colour', () => {
    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('have.class', 'selected');
    cy.get('tbody tr').first().should('have.css', 'background-color').and('not.equal', 'rgba(0, 0, 0, 0)');

    const selectedRowBgColor = cy.get('tbody tr.selected').then(($row) => {
      return window.getComputedStyle($row[0]).backgroundColor;
    });

    cy.get('tbody tr').eq(1).then(($unselectedRow) => {
      const unselectedBgColor = window.getComputedStyle($unselectedRow[0]).backgroundColor;
      selectedRowBgColor.then((selectedColor) => {
        expect(selectedColor).not.to.equal(unselectedBgColor);
      });
    });
  });

  it('should remove highlight from previously selected row when selecting a new row', () => {
    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('have.class', 'selected');

    cy.get('tbody tr').eq(1).click();
    cy.get('tbody tr').first().should('not.have.class', 'selected');
    cy.get('tbody tr').eq(1).should('have.class', 'selected');
  });

  it('should allow multiple row selection with highlight when ctrl/cmd key is pressed', () => {
    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('have.class', 'selected');

    cy.get('tbody tr').eq(1).click({ ctrlKey: true });
    cy.get('tbody tr').first().should('have.class', 'selected');
    cy.get('tbody tr').eq(1).should('have.class', 'selected');
  });

  it('should deselect row and remove highlight when clicking on already selected row', () => {
    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('have.class', 'selected');

    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('not.have.class', 'selected');
  });

  it('should maintain highlight when scrolling through table rows', () => {
    cy.get('tbody tr').first().click();
    cy.get('tbody tr').first().should('have.class', 'selected');

    cy.get('table').scrollTo('bottom');
    cy.get('tbody tr').first().should('have.class', 'selected');
  });

  it('should handle edge case of selecting row in empty table', () => {
    cy.get('tbody').then(($tbody) => {
      if ($tbody.find('tr').length === 0) {
        cy.get('tbody').should('be.empty');
      } else {
        cy.get('tbody tr').first().click();
        cy.get('tbody tr').first().should('have.class', 'selected');
      }
    });
  });
});
